import {SupportStore,type SupportTurn} from '../../lib/support-store';
import {CustomerAccountStore} from '../../lib/customer-account-store';
import {customerAccountSubjectKey} from '../../lib/customer-account-core';
import {resolveEffectiveSupportPreferences} from '../../lib/effective-support-preferences';

type Env={DB:D1Database;QA_SUPPORT_PREFERENCE_TOKEN:string;QA_SUPPORT_PREFERENCE_WORKSPACE:string};
const VISITOR='a'.repeat(64),GOOGLE_SUBJECT='synthetic-support-preference-subject',FINGERPRINT='d'.repeat(64);
const ACCOUNT_ID='93c16a95-7fc4-4bc2-8d2c-d3b0bff0a224';
const VISIT_ID='f1010101-0101-4101-8101-010101010101',BOOKING_EVENT_KEY='f2020202-0202-4202-8202-020202020202',HELP_EVENT_KEY='f3030303-0303-4303-8303-030303030303';
const SESSION_HASHES={first:'c'.repeat(64),revoked:'e'.repeat(64),forgotten:'f'.repeat(64)};
let activeSessionHash=SESSION_HASHES.first;
let fixtureNow=Date.UTC(2026,9,30,12,0,0);
const json=(value:unknown,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function stores(env:Env){return {support:new SupportStore(env.DB,env.QA_SUPPORT_PREFERENCE_WORKSPACE,undefined,()=>fixtureNow),accounts:new CustomerAccountStore(env.DB,env.QA_SUPPORT_PREFERENCE_WORKSPACE,()=>fixtureNow)};}
async function identity(workspace:string){return {subjectKey:await customerAccountSubjectKey(workspace,'https://accounts.google.com',GOOGLE_SUBJECT),sessionHash:activeSessionHash,googleSubject:GOOGLE_SUBJECT,fingerprint:FINGERPRINT};}
async function addGoogleSession(env:Env,sessionHash:string){const workspace=env.QA_SUPPORT_PREFERENCE_WORKSPACE,now=fixtureNow;await env.DB.prepare("INSERT INTO customer_google_prefill_sessions(session_hash,workspace_id,issuer,google_subject,profile_ciphertext,config_fingerprint,expires_at,created_at,intent_return_to,intent_expires_at,intent_consumed_at,browser_hash,revoked_at,intent_purpose,visit_ref) VALUES(?,?,'https://accounts.google.com',?,'synthetic-profile-ciphertext',?,?,?,'book',?,NULL,?,NULL,'account',NULL)").bind(sessionHash,workspace,GOOGLE_SUBJECT,FINGERPRINT,now+3600000,now,now+300000,'b'.repeat(64)).run();}
async function seed(env:Env){const workspace=env.QA_SUPPORT_PREFERENCE_WORKSPACE,now=fixtureNow,subjectKey=await customerAccountSubjectKey(workspace,'https://accounts.google.com',GOOGLE_SUBJECT),support=new SupportStore(env.DB,workspace,undefined,()=>fixtureNow);await support.createSession(VISITOR);await env.DB.batch([
 env.DB.prepare('INSERT INTO app_credential_state(project_id,revision,sealed_at,operation_token) VALUES(?,7,NULL,NULL)').bind(workspace),
 env.DB.prepare('INSERT INTO customer_accounts(id,workspace_id,subject_key,revision,created_at,expires_at,deleted_at,erased_at,operation_token,last_request_key,last_request_hash) VALUES(?,?,?,2,?,?,NULL,NULL,NULL,NULL,NULL)').bind(ACCOUNT_ID,workspace,subjectKey,now,now+30*86400000),
 env.DB.prepare('INSERT INTO customer_account_preferences(account_id,workspace_id,revision,preferences_json,expires_at,updated_at) VALUES(?,?,2,?,?,?)').bind(ACCOUNT_ID,workspace,JSON.stringify({remember:true,answerLength:'short',serviceInterests:['fall_blowout']}),now+30*86400000,now),
]);activeSessionHash=SESSION_HASHES.first;await addGoogleSession(env,activeSessionHash);return {subjectKey};}
async function migrationCount(env:Env){const row=await env.DB.prepare('SELECT COUNT(*) AS count FROM d1_migrations').first<{count:number}>();return Number(row?.count??0);}
async function tablePresent(env:Env,name:string){return !!await env.DB.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").bind(name).first();}
async function count(env:Env,table:string,workspace:string){const row=await env.DB.prepare(`SELECT COUNT(*) AS count FROM ${table} WHERE workspace_id=?`).bind(workspace).first<{count:number}>();return Number(row?.count??0);}
async function snapshot(env:Env){const workspace=env.QA_SUPPORT_PREFERENCE_WORKSPACE;const [turns,completed,accounts,prefs]=await Promise.all([count(env,'support_turns',workspace),env.DB.prepare("SELECT COUNT(*) AS count FROM support_turns WHERE workspace_id=? AND status='complete'").bind(workspace).first<{count:number}>(),count(env,'customer_accounts',workspace),count(env,'customer_account_preferences',workspace)]);return {turns,completed:Number(completed?.count??0),accounts,prefs};}

export default {async fetch(request:Request,env:Env){if(request.headers.get('x-qa-support-preference')!==env.QA_SUPPORT_PREFERENCE_TOKEN||new URL(request.url).hostname!=='127.0.0.1')return json({error:'fixture_unavailable'},404);if(request.method!=='POST')return json({error:'method_not_allowed'},405);let body:Record<string,unknown>;try{body=await request.json() as Record<string,unknown>;}catch{return json({error:'invalid_request'},400);}try{const {support,accounts}=stores(env),workspace=env.QA_SUPPORT_PREFERENCE_WORKSPACE,action=new URL(request.url).pathname.replace(/^\/__qa\//,'');
 if(action==='init'){const migrations=await migrationCount(env),column=await env.DB.prepare("SELECT 1 FROM pragma_table_info('support_turns') WHERE name='preference_context_json'").first(),counts=await snapshot(env);return json({ready:migrations===30&&!!column&&counts.turns===0&&counts.accounts===0&&counts.prefs===0,migrations,contextColumn:!!column,counts});}
 if(action==='seed'){const result=await seed(env);return json({seeded:true,subjectKeyPresent:!!result.subjectKey});}
 if(action==='record-booking'){const result=await accounts.recordInteraction(VISITOR,{visitId:VISIT_ID,requestKey:BOOKING_EVENT_KEY,event:'booking_opened',context:'support-booking'},await identity(workspace));return json({recorded:result.recorded,duplicate:result.duplicate});}
 if(action==='begin'){if(typeof body.requestKey!=='string'||!/^[a-zA-Z0-9_-]{16,80}$/.test(body.requestKey))throw new Error('fixture_invalid');const currentIdentity=await identity(workspace),request=new Request('https://fixture.test/support'),resolved=await resolveEffectiveSupportPreferences(request,VISITOR,{store:support,accountStore:accounts,getIdentity:async()=>currentIdentity}),input={requestKey:body.requestKey,message:'What demo services do you offer?'},begun=await support.beginTurn(VISITOR,input,resolved.context);return json({begun:!begun.replayed,turnId:begun.turn.id,threadId:begun.turn.thread_id,threadRevision:begun.turn.thread_revision,source:resolved.context.source,accountRevision:resolved.context.accountRevision});}
 if(action==='record-help'){if(typeof body.threadId!=='string'||typeof body.threadRevision!=='number')throw new Error('fixture_invalid');const result=await accounts.recordInteraction(VISITOR,{visitId:VISIT_ID,requestKey:HELP_EVENT_KEY,event:'help_thread_started',threadId:body.threadId,threadRevision:body.threadRevision},await identity(workspace));return json({recorded:result.recorded,duplicate:result.duplicate});}
 if(action==='export-help'){const currentIdentity=await identity(workspace),result=await accounts.export(currentIdentity.subjectKey);return json({helpReferences:result.interactions.filter(item=>item.event==='help_thread_started').map(item=>item.reference)});}
 if(action==='save'){const currentIdentity=await identity(workspace),result=await accounts.savePreferences(currentIdentity,body.value);return json({revision:result.revision,remember:result.preferences.remember,answerLength:result.preferences.answerLength,serviceInterests:result.preferences.serviceInterests});}
 if(action==='forget'){const currentIdentity=await identity(workspace),result=await accounts.forget(currentIdentity,body.value,VISITOR);return json({revision:result.revision,remember:result.preferences.remember,exists:result.exists});}
 if(action==='rotate-session'){const next=body.kind==='revoked'?SESSION_HASHES.revoked:SESSION_HASHES.forgotten;await addGoogleSession(env,next);activeSessionHash=next;return json({rotated:true});}
 if(action==='revoke-session'){await env.DB.prepare('UPDATE customer_google_prefill_sessions SET revoked_at=? WHERE workspace_id=? AND session_hash=?').bind(fixtureNow,workspace,activeSessionHash).run();return json({revoked:true});}
 if(action==='complete'){if(typeof body.requestKey!=='string')throw new Error('fixture_invalid');const turn=await env.DB.prepare('SELECT * FROM support_turns WHERE workspace_id=? AND visitor_hash=? AND request_key=?').bind(workspace,VISITOR,body.requestKey).first<SupportTurn>();if(!turn)throw new Error('fixture_not_found');const committed=await support.completeTurn(VISITOR,turn,{status:'answered',answer:'Synthetic preference-fence answer',actions:[]},[]),row=await env.DB.prepare('SELECT status,answer,result_json,preference_context_json FROM support_turns WHERE id=? AND workspace_id=?').bind(turn.id,workspace).first<{status:string;answer:string|null;result_json:string|null;preference_context_json:string|null}>();let contextKeys:string[]=[];try{contextKeys=Object.keys(JSON.parse(row?.preference_context_json??'{}')).sort();}catch{}return json({committed,status:row?.status??null,answerStored:row?.answer!==null&&row?.answer!==undefined,resultStored:row?.result_json!==null&&row?.result_json!==undefined,contextKeys,containsProfileFields:contextKeys.some(key=>['name','email','googleSubject','profile','photo','message','url'].includes(key)),counts:await snapshot(env)});}
 if(action==='replay-check'){if(typeof body.requestKey!=='string')throw new Error('fixture_invalid');const input={requestKey:body.requestKey,message:'What demo services do you offer?'},begun=await support.beginTurn(VISITOR,input),turn=begun.turn;let contextRejected=false;try{await support.currentContext(VISITOR,turn);}catch{contextRejected=true;}return json({replayed:begun.replayed,contextRejected,status:turn.status,answerStored:turn.answer!==null,resultStored:turn.result_json!==null});}
 if(action==='snapshot')return json(await snapshot(env));
 throw new Error('fixture_unavailable');
 }catch(error){const message=error instanceof Error?error.message:'fixture_failure';return json({error:/^(fixture_invalid|fixture_not_found|account_changed|request_conflict|identity_unavailable)$/.test(message)?message:'fixture_failure'},409);}}};
